-- The cited hadith's display block, denormalised onto every dorar_hadith row.
--
-- The site shows narrator, grader, grade, takhrij and categories for the one
-- row a page relies on. For situation and intention rows that was results->0;
-- for the original saying rows it was buried in a 15-row grading spread with
-- nothing marking the chosen one. Rather than teach the reader to guess,
-- `cited` stores the DorarRef verbatim as the client has always shaped it:
-- {rawi, mohdith, grade, id, takhrij?, categories}. Backfilled from the mock
-- files, which were themselves transcribed verbatim from dorar.net.

alter table dorar_hadith add column cited jsonb;

update dorar_hadith set cited = $j${"rawi":"الزبير بن العوام","mohdith":"البخاري","grade":"[صحيح]","id":"TlhsVKy7","takhrij":"من أفراد البخاري على مسلم","categories":[{"id":"75d058ec96950869518fea20949c0f55","name":"إجارة - كسب الرجل وعمله بيده"},{"id":"3ef1c2bc955f3fdb751925c8550ffd5b","name":"رقائق وزهد - فضل العمل والتكسب"},{"id":"8aef06e13cbc50b896c50f9123695242","name":"سؤال - النهي عن المسألة"},{"id":"b881f83f1e3637f3e20a758ac2cf7528","name":"سؤال - ذم السؤال"},{"id":"b3649739b68d8da7d8784096a0d85ff1","name":"سؤال - فضل التعفف والتصبر"}]}$j$::jsonb where slug = 'teach-a-man-to-fish';
